mapper.select:
SELECT id, student_id, report_date, submitted_at, free_text, created_at, updated_at
FROM daily_reports
WHERE student_id = #{studentId} AND report_date = #{reportDate}

SELECT id, student_id, report_date, submitted_at, free_text, created_at, updated_at
FROM daily_reports
WHERE id = #{id}

mapper.update:
UPDATE daily_reports
SET free_text = #{freeText}
WHERE id = #{id}

UPDATE daily_reports
SET submitted_at = #{submittedAt}
WHERE id = #{id}
